import{_ as o,l as s,o as e,c as i,v as t,p as n,x as l,d as B,i as m,S as b}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"StableLM 2","description":"","frontmatter":{"title":"StableLM 2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/stablelm2.md","filePath":"llm/stablelm2.md","lastUpdated":1789023840000}'),d={name:"llm/stablelm2.md"};function p(h,a,c,A,E,S){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="stablelm-2" tabindex="-1">StableLM 2 <a class="header-anchor" href="#stablelm-2" aria-label="Permalink to &quot;StableLM 2&quot;">​</a></h1><div class="epigraph"><p>把数据表、学习率日程和 1.6B 的训练小时数摊开，是为了让「小于 2B 的开源点」可以被复现，而不是只下载一份排行榜权重。</p><footer>—— Bellagente 等，Stable LM 2 1.6B Technical Report，arXiv:2402.17834</footer></div><p>Stability AI 的 StableLM 2 是 2024 年的小模型一代：<strong>1.6B</strong> 有完整技术报告，随后放出 <strong>12B</strong>（约 12.1B 参数）共用同一条「Stable LM 2」产品线。1.6B 训在约 <strong>2T</strong> 公开可商用语料上，七种欧洲语言，报告发布时自称 2B 以下开源明显领先；12B 模型卡写明在多样多语与代码数据上训 <strong>2T token、两轮</strong>。本篇以 2402.17834 为 1.6B 的出处，12B 只引用 Hugging Face 模型卡与同一份报告的引用栏，<strong>不为 12B 伪造独立 arXiv</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>小模型若只给权重、不给混合比例与日程，社区只能用更大模型蒸馏或猜数据。Stability 要把 1.6B 写成可审计实验：全部数据源公开、采样权重列表化、约 <strong>9.2 万 GPU 小时</strong>（报告按每卡时 3.5 美元估云成本）。问题因此是两层：在 24 层、\\(d=2048\\)、上下文 4096 的解码器上，如何用公开网页、代码与多语把「小于 2B」的英语与多语基准打满；以及后训练（SFT、DPO、自我知识）能否在不引入多语对齐数据的前提下把对话抬上去。</p><p>12B 要回答的产品问题不同：单机可部署的 12B 稠密模型，用 <a href="/llm/gqa">GQA</a> 和逐头 QK 归一化把服务 KV 与训练稳定钉住。它的数据叙事与 1.6B 同源（RefinedWeb、RedPajama、The Pile 去 Books3、StarCoder、CulturaX 等），但架构表、许可条款以 12B 模型卡为准。</p><h3 id="_1-6b-不是把-llama-缩到-24-层那么简单" tabindex="-1">1.6B 不是把 Llama 缩到 24 层那么简单 <a class="header-anchor" href="#_1-6b-不是把-llama-缩到-24-层那么简单" aria-label="Permalink to &quot;1.6B 不是把 Llama 缩到 24 层那么简单&quot;">​</a></h3><p>结构接近 Llama 式解码器，但报告列明差异：RoPE 只加在每个头的前 <strong>25%</strong> 维（GPT-NeoX 式，为吞吐）；归一化用带学习偏置的 LayerNorm，而不是 RMSNorm；FFN 与注意力里去掉大部分 bias，<strong>保留 Q/K/V 投影的 bias</strong>。词表是 Arcade100k——从 <code>tiktoken</code> 的 <code>cl100k_base</code> 扩出代码特殊符号与数字切分，训练时 pad 到 100352 以对齐 Tensor Core。1.6B 形状：参数约 16.4 亿，隐藏 2048，24 层，32 头，序列 4096。12B 模型卡：隐藏 5120，40 层，32 查询头 / <strong>8</strong> KV 头，序列 4096。</p><p><span class="marginnote">1.6B 报告表没有 GQA；12B 才是 32/8。不要把两档写成同一套注意力。许可是 Stability AI Community License，商用要看当时条款，不是 Apache 2.0。12B 模型卡语言栏写 English，但预训练混合含 CulturaX 多语——产品「官方语言」与数据里出现过的语言不是一回事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>1.6B 预训练在 512 张 A100 40GB 上，ZeRO-1，关掉激活检查点以换微批，全局约 \\(2^{23}\\) token/步，报告约 170 TFLOPs/s、54.5% MFU。AdamW：\\(\\beta_1=0.9\\)，\\(\\beta_2=0.95\\)，weight decay 0.1。混合精度 BF16，All-Reduce 走 FP32。他们消融过 softmax 上的 z-loss，觉得对稳定帮助有限，<strong>最终主实验没用</strong>。</p><p>数据表（报告 Table 1）按采样权重列出 ArXiv、PubMed、S2ORC、书籍、CulturaX 英/西/德/法/意/荷/葡、C4、OpenWebText2、RefinedWeb、StackExchange、法律、数学、Wiki、StarCoder、以及 Yuan &amp; Liu 风格的 Restruct-v1 指令化语料。CulturaX 的 mC4 因 HTML boilerplate 被丢掉，只留 OSCAR 子集。总有效 token 约 <strong>2.01T</strong>。消融在附录，用来选多语与代码比例。</p><h3 id="可续训的学习率-余弦接-rsqrt-再线性降到零" tabindex="-1">可续训的学习率：余弦接 rsqrt，再线性降到零 <a class="header-anchor" href="#可续训的学习率-余弦接-rsqrt-再线性降到零" aria-label="Permalink to &quot;可续训的学习率：余弦接 rsqrt，再线性降到零&quot;">​</a></h3><p>预热约 9720 步升到 \\(10^{-3}\\)。主段先按余弦降到 \\(N/4\\) 步，再切到</p> \\[\\eta(i)=\\frac{\\alpha}{\\sqrt{i+\\beta}}, \\]<p>\\(\\alpha,\\beta\\) 选成在衔接点函数值与导数连续。最后约 8 万步（约 670B token）线性降到 0。动机是：余弦把终点写死，想多训只能重来；rsqrt 段允许「还没决定总步数」时继续，最后一段冷却收盆地。这与后来小模型常用的 <a href="/llm/minicpm">WSD</a> 平台+衰减是同一类灵活性，形状不同。</p><p>后训练三步且<strong>不用多语数据</strong>：SFT → DPO → 自我知识。指令档以 <code>stablelm-2-zephyr-1_6b</code> 等名字发布。12B 预训练两轮、384 张 H100 量级（模型卡叙述），实现库 GPT-NeoX；逐头 QK-Norm 引用 ViT 与 Wortsman 等稳定化工作。</p>',17)),(e(),n(b,null,{default:l(()=>[m(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIX%5B%22%E5%85%AC%E5%BC%80%E7%BD%91%E9%A1%B5%20%2F%20%E4%BB%A3%E7%A0%81%20%2F%20%E4%B8%83%E8%AF%AD%20CulturaX%22%5D%20--%3E%20PT%5B%221.6B%20%E9%A2%84%E8%AE%AD%E7%BB%83%202T%22%5D%0A%20%20PT%20--%3E%20LR%5B%22%E9%A2%84%E7%83%AD%20%E2%86%92%20%E4%BD%99%E5%BC%A6%20%E2%86%92%20rsqrt%20%E2%86%92%20%E7%BA%BF%E6%80%A7%E5%86%B7%E5%8D%B4%22%5D%0A%20%20LR%20--%3E%20BASE%5B%22StableLM%202%201.6B%20Base%22%5D%0A%20%20BASE%20--%3E%20SFT%5B%22SFT%22%5D%0A%20%20SFT%20--%3E%20DPO%5B%22DPO%22%5D%0A%20%20DPO%20--%3E%20SK%5B%22%E8%87%AA%E6%88%91%E7%9F%A5%E8%AF%86%22%5D%0A%20%20SK%20--%3E%20ZEP%5B%22Zephyr%20%E6%8C%87%E4%BB%A4%E6%A1%A3%22%5D%0A%20%20MIX%20--%3E%20B12%5B%2212B%EF%BC%9AGQA%2032%2F8%20%2B%20QK-Norm%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>小模型的知识密度更吃数据混合而不是深度。1.6B 把 RefinedWeb 与 CulturaX 英语放到最大权重，代码与数学各占几个百分点，Restruct 把下游格式提前写进预训练，减少「只会续写网页」到「会答题」的落差。RoPE 只转 25% 维是吞吐权衡：旋转更少的通道，GEMM 更整；外推能力不能按「全头 RoPE」的经验外推。Arcade100k 对代码与非英语压缩更好，英语下游在报告的对照里与 NeoX 词表无显著差——选它是为多语和代码账单，不是为刷英语 MMLU。</p><p>rsqrt 段的机制是让学习率随步数缓慢下降而不预设终点，优化器仍有足够噪声去吃新数据；线性冷却才把权重推进低损失区。因此「最后 670B 很重要」是日程相位，不是那一段语料突然变神。后训练关掉多语，是为了把有限的 1.6B 容量花在英语对话；多语能力主要来自预训练，指令档的多语对话不要期望与英语 MT-Bench 同一水平。</p><p><span class="marginnote">报告 Table 4 把 Phi 标成 aligned，理由是教材式数据与问答意图，即使它们声称只预训练。和 <a href="/llm/phi">Phi</a> 比，StableLM 2 走的是公开网页混合 + 透明日程，不是合成教材。两者都「小打大」，数据哲学不同。</span></p><h3 id="_1-6b-与-12b、与-smollm-mobilellm" tabindex="-1">1.6B 与 12B、与 SmolLM / MobileLLM <a class="header-anchor" href="#_1-6b-与-12b、与-smollm-mobilellm" aria-label="Permalink to &quot;1.6B 与 12B、与 SmolLM / MobileLLM&quot;">​</a></h3><p>端侧吞吐与量化，报告给了 1.6B 的设备剖面；要本地助手先看 1.6B 指令档。12B 是单卡或双卡服务档，KV 靠 GQA 8 头，不要用 1.6B 的 32 头满 KV 去估 12B 显存。与 <a href="/llm/smollm">SmolLM</a> 比，StableLM 2 更早摊开完整源表；SmolLM 更强调教育过滤与合成教材。与 <a href="/llm/mobilellm">MobileLLM</a> 比，1.6B 不是为手机 SRAM 深度优先而设计，而是云侧可复现的 2B 以下点。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>12B 没有与 1.6B 等长的独立技术报告，架构与 token 量以模型卡为准，不要把 1.6B 的 24 层日程线性乘到 40 层。Community License 含使用与归因约束。Books3 被明确排除。z-loss 未进主实验，不能把别家的 logits 压制当成 StableLM 2 的默认实现。从 StableLM 3B 4e1t 等前代接 LoRA，层数与词表都不兼容。</p><p>指令档的 MT-Bench 与 Open LLM 平均分会随对照集变。量化检查点的表在报告里有，和 BF16 主表不是同一列。自我知识步骤的数据与提示以报告第三节为准，不要写成通用 DPO 的第四损失项。</p><p><span class="marginnote">真实编号只有 Bellagente 等 <em>Stable LM 2 1.6B Technical Report</em>，arXiv:2402.17834。12B 模型卡的 bibtex 仍指向这一号。不要编造 12B 专有 arXiv。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>StableLM 2 含 1.6B（完整报告、约 2T、七语、可续训学习率）与 12B（模型卡：GQA、QK-Norm、2T×两轮）。</li><li>架构近 Llama，但 RoPE 25% 维、LayerNorm、部分 QKV bias、Arcade100k。</li><li>后训练为英语 SFT+DPO+自我知识；许可为 Stability 社区条款。</li><li>出处：Bellagente 等，arXiv:2402.17834，2024；12B 以 Stability 模型卡为准。</li></ul>',12))])}const T=o(d,[["render",p]]);export{g as __pageData,T as default};
